fn solve(a: i8, b: i8, f: i8, k: i8) -> i8 {
    // Check basic impossibility conditions
    // Can't reach station from start
    if b < f {
        return -1;
    }
    
    // Can't reach end from station
    if b < a - f {
        return -1;
    }
    
    // For multiple journeys, check the critical constraint
    // After refueling at station going one direction, we need to reach
    // the station again on the return journey
    if k > 1 && b < 2 * a - f {
        return -1;
    }
    
    // Special case: single journey
    if k == 1 {
        // If we can make it without refueling
        if b >= a {
            return 0;
        }
        // Otherwise we need to refuel (and we know it's possible from checks above)
        return 1;
    }
    
    // Multiple journeys: simulate to check if refueling is needed
    let mut fuel = b;
    let mut needs_refuel = false;
    
    for journey in 1..=k {
        let to_station: i8;
        let from_station: i8;
        
        if journey % 2 == 1 {
            // Odd journey: start to end
            to_station = f;
            from_station = a - f;
        } else {
            // Even journey: end to start
            to_station = a - f;
            from_station = f;
        }
        
        // Travel to station
        fuel -= to_station;
        
        // Check if we need to refuel at the station
        // We need to refuel if we can't complete the rest of this journey
        // or (if not the last journey) can't reach the station on the next journey
        let distance_needed = if journey == k {
            from_station
        } else {
            // Need to complete this journey and reach station on next journey
            if journey % 2 == 1 {
                // Currently going to end, next will go back
                from_station + (a - f)
            } else {
                // Currently going to start, next will go forward
                from_station + f
            }
        };
        
        if fuel < distance_needed {
            fuel = b;
            needs_refuel = true;
        }
        
        // Complete the journey
        fuel -= from_station;
    }
    
    if needs_refuel {
        1
    } else {
        0
    }
}